solution.main.cpp:
#include <iostream>

int main()
{
    int hex{ 0xFF };
    int bin{ 0b1010 };
    int oct{ 010 };
    int million{ 1'000'000 };

    std::cout << hex << '\n';
    std::cout << bin << '\n';
    std::cout << oct << '\n';
    std::cout << million << '\n';
    return 0;
}
